/* Clip library for the mocap rig viewer: which library clip plays each spec clip key, per race.
 *
 * Source: Quaternius Universal Animation Library 1 and 2 (CC0), converted with ual_to_bvh.js into library/ual/.
 * Clip keys follow specs/core/rendering-animation.md section 5c. The viewer reads each race's required keys from
 * prompts/<race>.txt (generated by prompts/build_prompts.py), so required clips with no entry here are listed as gaps
 * to generate with animgen. Extra keys (fidgets, extra attack variants, work clips) are spec names outside the minimum sets.
 *
 * Entry fields:
 *   src     library clip name, or a list of names played one after another (attack + recovery)
 *   range   [first, last] frame (30 fps) after joining, to cut one move out of a longer combo
 *   speed   playback speed (0.8 = 25% slower: heavier bodies)
 *   mirror  swap left and right (the source uses the other hand)
 *   opts    retarget settings this clip needs, applied over the sidebar (library clips default to in place, IK off)
 *   note    shown in the clip list: why this source, or what is off about it
 */
(function (root) {
  'use strict';

  const SMASH = { src: 'Sword_Heavy_Combo', range: [63, 120], opts: { ik: true, ikTargetY: 0 },
                  note: 'overhead downstroke cut from the heavy combo; weapon IK puts the tip on the ground' };

  // humanoid defaults; races below override single keys
  const HUMANOID = {
    'move.idle': { src: 'Idle_Loop' },
    'move.idle.1': { src: 'Idle_FoldArms_Loop', note: 'fidget: arms folded' },
    'move.walk': { src: 'Walk_Loop' },
    'move.run': { src: 'Jog_Fwd_Loop' },
    'move.march': { src: 'Walk_Formal_Loop', note: 'upright formal walk' },
    'move.flee': { src: 'Sprint_Loop', note: 'sprint; the turn away comes from the AI, not the clip' },
    'move.charge': { src: 'Sprint_Loop', note: 'sprint; arm not raised' },
    'move.sneak': { src: 'Crouch_Fwd_Loop' },
    'move.swim': { src: 'Swim_Fwd_Loop' },
    'move.climb': { src: 'ClimbUp_1m' },
    'pose.sit': { src: 'Sitting_Idle_Loop', note: 'chair height: hips at 54 cm' },
    'react.hurt': { src: 'Hit_Chest' },
    'react.hurt.1': { src: 'Hit_Head' },
    'react.knockdown': { src: 'Hit_Knockback' },
    'react.death': { src: 'Death01' },
    'attack.unarmed.1': { src: 'Punch_Cross' },
    'attack.unarmed.2': { src: 'Punch_Jab', note: 'left-hand jab' },
    'attack.sword.1': { src: 'Sword_Attack', note: 'diagonal overhead chop' },
    'attack.sword.2': { src: ['Sword_Regular_B', 'Sword_Regular_B_Rec'], note: 'waist-high horizontal slash + recovery' },
    'attack.sword.3': { src: ['Sword_Regular_A', 'Sword_Regular_A_Rec'], note: 'rising slash + recovery' },
    'attack.throw.1': { src: 'OverhandThrow' },
    'hold.sword': { src: 'Sword_Idle', note: 'guard stance, knees bent' },
    'hold.torch': { src: 'Idle_Torch_Loop', note: 'torch in the left hand' },
    'defend.block.shield': { src: 'Shield_OneShot' },
    'defend.brace.shield': { src: 'Idle_Shield_Loop' },
    'defend.block.weapon': { src: 'Sword_Block' },
    'social.talk': { src: 'Idle_Talking_Loop' },
    'emote.order': { src: ['Spell_Simple_Enter', 'Spell_Simple_Shoot', 'Spell_Simple_Exit'], mirror: true,
                     note: 'arm thrust forward (spell cast, mirrored to the right arm); no shout in the body' },
    'work.farm': { src: 'Farm_Harvest' },
    'work.mine': { src: 'TreeChopping_Loop', note: 'tree-chopping swing as a pickaxe stand-in' },
    'work.smith': { src: 'TreeChopping_Loop', note: 'stand-in: no hammer-on-anvil clip in the packs' },
    'work.chop': { src: 'TreeChopping_Loop' },
    'work.carry': { src: 'Walk_Carry_Loop' },
    'ride.idle': { src: 'Driving_Loop', note: 'seated, hands forward as on reins' },
    'ranged.crossbow.aim': { src: 'Pistol_Idle_Loop', note: 'two-handed aim at shoulder height' },
    'ranged.crossbow.reload': { src: 'Pistol_Reload', note: 'rough stand-in' },
  };

  const pick = (from, keys) => Object.fromEntries(keys.filter((k) => from[k]).map((k) => [k, from[k]]));
  const slower = (e, speed) => Object.assign({}, e, { speed });

  const ORC = Object.assign({}, HUMANOID, {
    'move.idle.1': { src: 'Zombie_Idle_Loop', note: 'fidget: slack, hunched sway' },
    'attack.unarmed.1': { src: ['Melee_Hook', 'Melee_Hook_Rec'], note: 'lunging hook + recovery' },
    'attack.sword.1': { src: 'Sword_Regular_C', note: 'feint then a big diagonal chop' },
    'attack.sword.3': HUMANOID['attack.sword.1'],
    'attack.sword.4': { src: 'Sword_Dash', note: 'lunge with a slash each way' },
  });

  const HEAVY = (speed) => ({
    'move.idle': { src: 'Zombie_Idle_Loop', note: 'slack, hunched idle' },
    'move.walk': slower({ src: 'Zombie_Walk_Fwd_Loop', note: 'lumbering walk' }, speed),
    'move.run': slower(HUMANOID['move.run'], speed),
    'move.charge': slower(HUMANOID['move.charge'], speed),
    'move.flee': slower(HUMANOID['move.flee'], speed),
    'react.hurt': slower(HUMANOID['react.hurt'], speed),
    'react.knockdown': slower(HUMANOID['react.knockdown'], speed),
    'react.death': slower(HUMANOID['react.death'], speed),
    'attack.smash.1': slower(SMASH, speed),
  });

  const RACES = {
    man: { label: 'Man', settings: {}, clips: HUMANOID },
    elf: { label: 'Elf', settings: {}, clips: Object.assign({}, HUMANOID, {
      'attack.unarmed.1': HUMANOID['attack.unarmed.2'],
      'attack.sword.2': HUMANOID['attack.sword.3'],
      'attack.sword.3': HUMANOID['attack.sword.2'],
    }) },
    dwarf: { label: 'Dwarf', settings: { stance: 1.2 }, clips: HUMANOID },
    hobbit: { label: 'Hobbit', settings: {}, clips: Object.assign({}, HUMANOID, {
      'attack.unarmed.1': HUMANOID['attack.unarmed.2'],
      'work.farm': { src: 'Farm_PlantSeed', note: 'kneels to plant' },
      'work.farm.1': HUMANOID['work.farm'],
    }) },
    orc: { label: 'Orc (orcs, goblins, Uruk-hai)', settings: {}, clips: ORC },
    olog: { label: 'Olog-hai', settings: { stance: 1.1 }, clips: Object.assign({}, ORC, {
      'move.walk': slower(ORC['move.walk'], 0.9), 'move.run': slower(ORC['move.run'], 0.9),
      'move.charge': slower(ORC['move.charge'], 0.9), 'attack.smash.1': SMASH,
    }) },
    half_troll: { label: 'Half-troll', settings: { stance: 1.1 }, clips: Object.assign(
      pick(ORC, ['pose.sit', 'react.hurt.1', 'attack.unarmed.1', 'attack.sword.1', 'attack.sword.2', 'hold.sword',
                 'defend.block.shield', 'social.talk', 'work.farm', 'work.smith', 'work.mine']),
      HEAVY(0.9)) },
    troll: { label: 'Troll', settings: { stance: 1.1, torsoTiltCap: 45 }, clips: Object.assign(HEAVY(0.8), {
      'attack.smash.2': { src: 'Zombie_Scratch', speed: 0.8, note: 'swat: downward swipe across the body' },
    }) },
  };

  /** Guess the race from a model file name (faction packs: <faction>_<unit>.bbmodel). */
  function raceForModel(name) {
    const n = (name || '').toLowerCase();
    if (/half_troll/.test(n)) return 'half_troll';
    if (/troll/.test(n)) return 'troll';
    if (/olog/.test(n)) return 'olog';
    if (/orc|uruk|goblin|snaga/.test(n)) return 'orc';
    for (const r of ['dwarf', 'elf', 'hobbit']) if (n.includes(r)) return r;
    return 'man';
  }

  const LIBRARY = {
    dir: 'library/ual/',
    credit: 'Universal Animation Library 1 and 2 by Quaternius (CC0)',
    defaults: { inPlace: true, ik: false },
    races: RACES,
    raceForModel,
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = LIBRARY;
  else root.ANIM_LIBRARY = LIBRARY;
})(typeof window !== 'undefined' ? window : globalThis);
